SourceCode.Declaration:
/// <summary>
/// This is an extension class for the VendParameters form METVendParameters datasource.
/// </summary>
[ExtensionOf(formDataSourceStr(VendParameters, METVendParameters))]
final class METVendParameters_METVendParametersDS_Extension
{   
    public SysLookupMultiSelectCtrl multiSelectControl;
    public SysLookupMultiSelectCtrl metDuplicateCheckOnSavingCTHeader;

}

Method.Source:
/// <summary>
/// Enable/disable the EnableMetcashMatchingLogic control.
/// </summary>
public void init()
{
    next init();

    FormControl taxinvTotToleranceCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_TaxInvTotalsToleranceDollar));
    FormControl totalPriceTolerancePercentage = this.formRun().design(1).controlName(formControlStr(VendParameters, METInvoiceMatching_TotalPriceTolerancePercentage));
    FormControl displayTotalPriceMatchIcon = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_DisplayTotalPriceMatchIcon));
    FormControl enableMetMatchCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_EnableMetcashMatchingLogic));
    FormControl defaultInvDate = this.formRun().design(1).controlName(formControlStr(VendParameters, VendParameters_METDefaultInvDate));
    FormControl metReasonCode = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_ReasonCode));
    FormControl displayHideCustomFields = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_DisplayHideCustomFields));

    METVendParameters metVendparm = METVendParameters::find();
    VendParameters vendparm = VendParameters::find();

    if (!vendparm.UseTotalPriceMatching)
    {
        enableMetMatchCtrl.enabled(true);

        if (metVendparm.EnableMetcashMatchingLogic)
        {
            taxinvTotToleranceCtrl.enabled(true);
            totalPriceTolerancePercentage.enabled(true);
            displayTotalPriceMatchIcon.enabled(true);
            defaultInvDate.enabled(true);
            metReasonCode.enabled(true);
            displayHideCustomFields.enabled(true);
        }
        else
        {
            taxinvTotToleranceCtrl.enabled(false);
            totalPriceTolerancePercentage.enabled(false);
            displayTotalPriceMatchIcon.enabled(false);
            defaultInvDate.enabled(false);
            metReasonCode.enabled(false);
            displayHideCustomFields.enabled(false);
        }
    }
    else
    {
        metVendparm.EnableMetcashMatchingLogic = NoYes::No;
        enableMetMatchCtrl.enabled(false);
        taxinvTotToleranceCtrl.enabled(false);
        totalPriceTolerancePercentage.enabled(false);
        displayTotalPriceMatchIcon.enabled(false);
        defaultInvDate.enabled(false);
        metReasonCode.enabled(false);
        displayHideCustomFields.enabled(false);
    }

    FormStringControl chargeThroughType = this.formRun().design(1).controlName(formControlStr(VendParameters, METChargeThroughType));

    FormStringControl vendDuplicateCheckOnSavingCTHeader = this.formRun().design(1).controlName(formControlStr(VendParameters,METVendDuplicateCheckOnSavingCTHeader));

    QueryRun queryRun = METChargeThroughInvEnumLookupTmp::buildQueryRun(enumNum(METInvoiceType));

    multiSelectControl = SysLookupMultiSelectCtrl::constructWithQueryRun(this.formRun(),
                                                                         chargeThroughType,
                                                                         queryRun);

    metDuplicateCheckOnSavingCTHeader = SysLookupMultiSelectCtrl::constructWithQueryRun(this.formRun(),
                                                                                        VendDuplicateCheckOnSavingCTHeader,
                                                                                        queryRun); 

    VendDuplicateCheckOnSavingCTHeader.text(vendparm.METDuplicateCheckOnSavingCTHeader);


    chargeThroughType.text(metVendparm.ChargeThroughInvoiceType);

}

/// <summary>
/// Active method trigger extension.
/// </summary>
/// <returns>Returns int as true/false.</returns>
public int active()
{
    int ret = next active();
    METVendParameters metVendparm = METVendParameters::find();

    FormControl rebateAccrualJournalName = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_RebateAccrualJournalName));
    FormControl holdInvoice = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendorRebatesGroup_HoldInvoice));

    rebateAccrualJournalName.enabled(metVendparm.VendorRebatesEnabled);
    holdInvoice.enabled(metVendparm.VendorRebatesEnabled);

    return ret;
}
